<template><el-card><template #header><div class="head"><span>退款审核</span><el-button :loading="loading" @click="load">刷新</el-button></div></template><el-table :data="rows" v-loading="loading"><el-table-column label="订单号"><template #default="s">{{ s.row.orderNo || s.row.orderNumber || (s.row.orderId ? `订单#${s.row.orderId}` : '-') }}</template></el-table-column><el-table-column label="退款金额"><template #default="s">¥{{ s.row.amount ?? s.row.refundAmount ?? '-' }}</template></el-table-column><el-table-column label="状态"><template #default="s">{{ ({PENDING_AUDIT:'待审核',APPROVED:'已同意',REJECTED:'已驳回'} as any)[s.row.status] || s.row.status || '-' }}</template></el-table-column><el-table-column label="申请原因"><template #default="s">{{ s.row.reason || s.row.reasonDesc || '-' }}</template></el-table-column><el-table-column label="驳回原因"><template #default="s">{{ s.row.rejectReason || '-' }}</template></el-table-column><el-table-column label="操作" width="190"><template #default="s"><el-button link @click="detail(s.row)">详情</el-button><template v-if="s.row.status==='PENDING_AUDIT'"><el-button link type="success" :loading="acting===s.row.id" @click="act(s.row,true)">同意</el-button><el-button link type="danger" :loading="acting===s.row.id" @click="act(s.row,false)">驳回</el-button></template></template></el-table-column></el-table><el-empty v-if="!loading&&!rows.length" description="暂无退款申请"/></el-card><el-dialog v-model="detailOpen" title="退款详情" width="500px"><el-descriptions v-if="current" :column="1" border><el-descriptions-item label="退款单号">{{current.refundNo}}</el-descriptions-item><el-descriptions-item label="订单号">{{current.orderNo}}</el-descriptions-item><el-descriptions-item label="退款金额">¥{{current.refundAmount}}</el-descriptions-item><el-descriptions-item label="申请原因">{{current.reasonDesc||'-'}}</el-descriptions-item><el-descriptions-item label="驳回原因">{{current.rejectReason||'-'}}</el-descriptions-item><el-descriptions-item label="积分回滚">{{preview?.resultText||'加载中…'}}</el-descriptions-item></el-descriptions><el-alert v-if="detailError" :title="detailError" type="error" show-icon/></el-dialog></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {refundApi} from '@/api';const rows=ref<any[]>([]),loading=ref(false),acting=ref<number|undefined>(),detailOpen=ref(false),current=ref<any>(),preview=ref<any>(),detailError=ref('');async function load(){loading.value=true;try{const response:any=await refundApi.list({status:'PENDING_AUDIT'});const envelope=response?.data??response;const data=envelope?.data??envelope;const list=data?.list??data?.items??data;rows.value=Array.isArray(list)?list:[]}catch(e:any){rows.value=[];ElMessage.error(e?.response?.data?.message||e?.message||'退款加载失败')}finally{loading.value=false}}async function detail(r:any){detailOpen.value=true;current.value=null;preview.value=null;detailError.value='';try{const [a,b]:any=await Promise.all([refundApi.detail(r.id),refundApi.rollbackPreview(r.id)]);current.value=a?.data??a;preview.value=b?.data??b}catch(e:any){detailError.value=e?.response?.data?.message||e?.message||'退款详情加载失败'}}async function act(r:any,yes:boolean){let reason='';if(!yes){try{const result:any=await ElMessageBox.prompt('请输入驳回原因（必填）','驳回退款',{inputValidator:(v)=>v?.trim()?true:'请输入驳回原因'});reason=result.value.trim()}catch{return}}acting.value=r.id;try{if(yes)await refundApi.approve(r.id);else await refundApi.reject(r.id,reason);ElMessage.success(yes?'已同意退款':'已驳回退款');await load()}catch(e:any){ElMessage.error(e?.response?.data?.message||e?.message||'操作失败')}finally{acting.value=undefined}}onMounted(load);</script><style scoped>.head{display:flex;align-items:center;justify-content:space-between}</style>
